function statusEffectHTML(name,value){return '<span class="status-help" tabindex="0">'+name+' '+(value>0&&name!=='呪い'?'+':'')+value+'<aside class="tooltip">'+(keywords[name]||name)+'</aside></span>';}
function enemyStatusValue(e,key){return typeof effectiveEnemyStatus==='function'?effectiveEnemyStatus(e,key):e[key]||0;}
function enemyStatusHTML(e){return '<div class="player-status enemy-status-list">'+[['str','筋力'],['agility','守護'],['poison','毒'],['plate','プレート'],['regen','再生'],['thorns','棘'],['freeze','凍結'],['curse','呪い'],['armorStrike','甲撃']].filter(([k])=>enemyStatusValue(e,k)).map(([k,n])=>statusEffectHTML(n,enemyStatusValue(e,k))).join('')+(e.poisonTotal?`<span class="status-help" tabindex="0">累積毒 ${e.poisonTotal}<aside class="tooltip">この戦闘中に付与された毒の合計。バフ・デバフではなく、毒の減少や謁見でリセットされません。</aside></span>`:'')+'</div>'}
function audienceBadge(e){return `<div class="audience-badge status-help" tabindex="0" aria-label="謁見${e.audienceUsed?'発動済み':''}">♛<strong>謁見</strong><small>${e.intent==='stunned'?'行動不能':e.audienceUsed?'発動済み':'未発動'}</small><aside class="tooltip">HP150以下になったターン、一度だけ自身の全バフ・デバフとブロックを解除してスタンし、筋力3を得る。その後、強力な攻撃を繰りだす。</aside></div>`}

function cardOrder(a,b){let order={common:0,rare:1,epic:2};return order[C[a].rarity]-order[C[b].rarity]||a-b}
// UI and interaction upgrade; original save key is retained.
const base={card,render,go,start,choose,next,play,endTurn,victory,reward,packs,take,relic,finish};
let busy=false,drag=null,bookType='cards',bookFilter='all',returnPage='home';
const keywords={筋力:'攻撃カードのダメージが、筋力の値だけ増加します。複数回攻撃では各攻撃に適用されます。',除外:'使用するとその戦闘中はデッキから隔離され、使用できなくなります。次の戦闘では戻ります。',ブロック:'受けるダメージを同じ値だけ軽減します。次の自分のターン開始時に消えます。',毒:'敵の行動前に、毒の値だけHPにダメージを与えます。その後、毒が1減ります。'};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rich(s){return s.replace(/筋力|除外|ブロック|再生|毒/g,k=>`<strong class="keyword">${k}</strong>`)}
function tips(c){return Object.keys(keywords).filter(k=>c.desc.includes(k)).map(k=>`<div><strong class="keyword">【${k}】</strong><p>${keywords[k]}</p></div>`).join('')}
card=function(id,action='',extra=''){let c=C[id],desc=c.desc,active=page==='battle'&&S.run;let enhanced=active&&c.fx.d&&S.run.str>0&&!c.runOnly;if(enhanced)desc=desc.replace(c.fx.d+'ダメージ',`<strong class="boost">${c.fx.d+S.run.str}ダメージ</strong>`);return `<div class="card-wrap"><button class="card ${c.rarity} ${active?(S.run.energy>=c.cost?(enhanced?'empowered':'playable'):'unplayable'):''}" ${action?`onclick="${action}"`:''} data-card="${id}"><span class="cost">${c.cost}</span><div class="art">${c.icon}</div><small>${c.rarity.toUpperCase()}</small><h3>${c.name}</h3><p>${rich(desc)}</p>${extra}</button>${tips(c)?`<aside class="tooltip">${tips(c)}</aside>`:''}</div>`};
function relicIcon(x){return {s:'♜',b:'◇',hp:'✚'}[x.type]||'✧'}
function relicsHTML(list,large=false){return `<div class="relic-list ${large?'large':''}">${list.map(x=>`<div class="relic-wrap" tabindex="0"><div class="relic-icon">${relicIcon(x)}</div>${large?`<h3>${x.name}</h3>`:''}<aside class="tooltip"><strong>${x.name}</strong><p>${x.desc}</p></aside></div>`).join('')||'<span class="muted">遺物なし</span>'}</div>`}
go=function(p){if(busy)return;if(p==='book'){returnPage=page;page=p;render();return}if(S.run&&p==='deck'){returnPage=page;page='deck';render();return}if(S.run&&['home','packs'].includes(p))return toast('ゲームオーバーまで探索を続けます');base.go(p)};
render=function(){if(globalThis.ASHBOUND_LOADING)return;base.render();$('nav').innerHTML+=`<button class="${page==='book'?'active':''}" onclick="go('book')">図鑑</button>`;if(page==='battle')wireBattle();if(page==='deck'&&!S.run)wireDeck();if(page==='battle')document.querySelectorAll('.card').forEach(c=>{c.onclick=null});save()};
const baseHome=home;home=function(){return baseHome().replace('敵の予告を見て攻撃と防御を選ぶ。','カードを敵にドラッグして攻撃。補助・全体攻撃はフィールドにドロップ。').replace('敗北しても獲得パックは持ち帰れる。','ゲームオーバーかボス撃破で拠点へ帰還。獲得パックは持ち帰れる。')};
function deckSlot(id,i,kind){return `<div class="deck-slot" data-zone="${kind}" data-index="${i}" data-id="${id}">${card(id,'',`<span class="count">${kind==='deck'?'デッキ内':'未使用'} <b class="quantity">${kind==='deck'?count(id):(S.collection[id]||0)-count(id)}枚</b></span>`)}</div>`}
deck=function(){let r=S.run;if(r){return `<div class="eyebrow">RUN DECK / READ ONLY</div><h2>探索中のデッキ</h2><p>潜在カードを含む ${r.deck.length} 枚。編成変更は帰還後に行えます。</p><button onclick="page=S.run.mode;render()">探索に戻る →</button><div class="cards deck-zone">${[...new Set(r.deck)].sort(cardOrder).map(id=>card(id,'',`<span class="count">デッキ内 <b class="quantity">${r.deck.filter(x=>x===id).length}枚</b></span>`)).join('')}</div>${r.mode==='battle'?`<p>山札 ${r.draw.length} ／ 手札 ${r.hand.length} ／ 捨札 ${r.discard.length} ／ 除外 ${(r.exhausted||[]).length}</p>`:''}`}
let spare=[];C.forEach(c=>{for(let i=0;i<(S.collection[c.id]||0)-count(c.id);i++)spare.push(c.id)});return `<div class="eyebrow">YOUR ARSENAL</div><h2>デッキの編成</h2><p>同じカードはまとめて表示。ドラッグ1回で1枚を追加・取り外し、別の領域のカードに落とすと1枚ずつ交換できます。</p><div class="deck-info"><b>${S.deck.length} / 20 枚</b><span>編成範囲 10〜20枚</span><button class="primary" onclick="start()">このデッキで出発 →</button></div><h3>使用するデッキ</h3><div class="cards deck-zone" data-drop="deck">${[...new Set(S.deck)].sort(cardOrder).map(id=>deckSlot(id,S.deck.indexOf(id),'deck')).join('')}</div><div class="section-head"><h3>未使用のカード</h3><span class="muted">${spare.length} 枚</span></div><div class="cards deck-zone reserve" data-drop="reserve">${[...new Set(spare)].sort(cardOrder).map(id=>deckSlot(id,spare.indexOf(id),'reserve')).join('')||'<p>未使用カードはありません。ここへドラッグして取り外せます。</p>'}</div>`};
function changeDeck(from,to,id,index,other){if(S.run)return false;if(from===to)return false;if(from==='reserve'){if(count(id)>=(S.collection[id]||0))return false;if(other!=null){S.deck[index]=id}else{if(S.deck.length>=20){toast('20枚です。デッキ内のカードに落として交換してください');return false}S.deck.push(id)}}else{if(S.deck[index]!==id)return false;if(other!=null){if(count(other)>=(S.collection[other]||0))return false;S.deck[index]=other}else{if(S.deck.length<=10){toast('10枚未満にはできません。未使用カードに落として交換してください');return false}S.deck.splice(index,1)}}render();return true}
function wireDeck(){document.querySelectorAll('.deck-slot').forEach(el=>el.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();drag={type:'deck',from:el.dataset.zone,id:+el.dataset.id,index:+el.dataset.index,startX:e.clientX,startY:e.clientY,moved:false,pointerId:e.pointerId,el};el.classList.add('drag-source');makeGhost(el,e)}))}
function makeGhost(el,e){let ghost=el.cloneNode(true);ghost.className='drag-ghost';ghost.id='drag-ghost';ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';document.body.append(ghost)}
function createMap(r){r.nodes=Array.from({length:10},(_,row)=>Array.from({length:row===9?1:3},(_,lane)=>({row,lane,type:row===9?'boss':row===0?(lane===1?'elite':'fight'):rand(['fight','fight','elite','rest','event']),edges:[]})));for(let row=0;row<9;row++)r.nodes[row].forEach(n=>{n.edges=row===8?[0]:r.nodes[row+1].filter(m=>Math.abs(m.lane-n.lane)<=1).map(m=>m.lane)});r.nodePath=[];r.act=r.act||1}
start=function(){base.start();if(S.run){createMap(S.run);render()}};
function available(n){let r=S.run;if(n.row!==r.floor-1)return false;let prev=r.nodePath?.at(-1);return !prev||r.nodes[prev.row][prev.lane].edges.includes(n.lane)}
map=function(){let r=S.run;if(!r.nodes)createMap(r);let pts=n=>({x:n.row===9?350:110+n.lane*240,y:70+(9-n.row)*112});let lines='';r.nodes.flat().forEach(n=>n.edges.forEach(l=>{let a=pts(n),b=pts(r.nodes[n.row+1][l]);lines+=`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" class="${r.nodePath.some(p=>p.row===n.row&&p.lane===n.lane)?'traversed':''}"/>`}));return `<div class="battle-top"><div><div class="eyebrow">THE FALLEN CITY / ACT ${r.act}</div><h2>廃都の探索路</h2></div><span class="tag">HP ${r.hp} / ${r.max}　▣ ${r.packs}　◈ ${r.gold}</span></div><p>下から上へ、線でつながったノードを選択。最上部に待つ王の撃破を目指します。ゲームオーバー、またはボス撃破で拠点へ帰還。</p><div class="map-layout"><div class="map-board"><svg viewBox="0 0 700 1138">${lines}</svg>${r.nodes.flat().map(n=>{let p=pts(n),used=r.nodePath.some(x=>x.row===n.row&&x.lane===n.lane),ready=available(n);let name={fight:'戦闘',elite:'強敵',event:'宝物庫',rest:'休息',boss:'ボス'}[n.type];return `<button class="map-node ${ready?'available':''} ${used?'visited':''}" style="left:${p.x/700*100}%;top:${p.y/1138*100}%" onclick="enterNode(${n.row},${n.lane})" ${!ready?'disabled':''} aria-label="第${n.row+1}階層 ${name}"><b>${{fight:'⚔',elite:'♜',event:'◇',rest:'✚',boss:'♛'}[n.type]}</b><span>${name}</span></button>`}).join('')}</div><aside class="map-side"><h3>携行遺物</h3>${relicsHTML(r.relics)}<p>明るいノードが選択可能。<br>選んだ道が今回のルートになります。</p></aside></div>`};
function enterNode(row,lane){let r=S.run,n=r.nodes[row]?.[lane];if(!n||!available(n)||busy)return;r.nodePath.push({row,lane});choose(n.type)}
choose=function(type){base.choose(type);let r=S.run;if(r&&page==='battle'){r.enemies.forEach(e=>{let boost=(r.act-1)*8;e.hp+=boost;e.max+=boost;e.atk+=(r.act-1)*2});render()}};
function hpbar(hp,max,block){return `<div class="bar"><i style="width:${hp/max*100}%"></i>${block?`<i class="shield-bar" style="width:${Math.min(100,block/max*100)}%"></i>`:''}</div>`}
battle=function(){let r=S.run;return `<div class="battle-top"><div><div class="eyebrow">ACT ${r.act||1} / FLOOR ${r.floor} / TURN ${r.turn}</div><h2>${r.kind==='boss'?'灰冠の王':r.kind==='elite'?'封鎖された聖堂':'崩れた街路'}</h2></div><div>${relicsHTML(r.relics)}</div></div><div class="arena"><div class="unit" data-entity="player"><div class="muted">探索者</div><div class="portrait" style="color:var(--gold)">⚔</div><h3>灰の契約者</h3>${hpbar(r.hp,r.max,r.block,r.max+(r.curseMaxLoss||0))}<p>♥ ${r.hp} / ${r.max}　◇ ${r.block}</p><div class="player-status">${r.str?`<span class="status-help" tabindex="0">筋力 +${r.str}<aside class="tooltip">${keywords.筋力}</aside></span>`:''}</div></div>${r.enemies.map((e,i)=>`<div class="unit ${e.hp<=0?'dead':''}" data-entity="${i}">${e.boss?audienceBadge(e):''}<div class="intent">${intent(e)}</div><div class="portrait">${e.icon}</div><h3>${e.name}</h3>${hpbar(e.hp,e.max,e.block)}<p>♥ ${e.hp} / ${e.max}　◇ ${e.block}</p>${enemyStatusHTML(e)}</div>`).join('')}</div><div class="combat-controls"><span class="energy">✧ ${r.energy} <small>/ 3</small></span><span class="muted">山札 ${r.draw.length}　捨札 ${r.discard.length}</span><button class="primary" onclick="endTurn()" ${busy?'disabled':''}>ターン終了 →</button></div><div class="cards hand">${r.hand.map(id=>card(id)).join('')}</div><p class="log" aria-live="polite">${busy?'行動中…':'単体攻撃は矢印を敵へ。補助・全体攻撃はカードをフィールドにドロップ。'}</p>`};
function wireBattle(){document.querySelectorAll('.hand .card').forEach((el,i)=>el.addEventListener('pointerdown',e=>{if(busy||S.run?.potionTarget!=null||S.run?.pendingChoice||S.run?.hunterChoice||S.run?.pendingDiscard||e.button!==0)return;let c=combatCard(S.run.hand[i]);if(typeof canPlayHunterCard==='function'&&!canPlayHunterCard(c,S.run))return toast('HP30%以下で使用できます');if(S.run.energy<c.cost)return toast('使用コストが足りません');e.preventDefault();let rect=el.getBoundingClientRect();if(!needsEnemy(c)){drag={type:'field',index:i,card:c};makeGhost(el,e);el.classList.add('drag-source');return}drag={type:'battle',index:i,card:c,x:rect.left+rect.width/2,y:rect.top+20};document.body.insertAdjacentHTML('beforeend','<svg id="aim" class="aim"><defs><marker id="head" markerWidth="9" markerHeight="9" refX="7" refY="3" orient="auto"><path d="M0 0L0 6L8 3Z" fill="#dfb96b"/></marker></defs><path id="aim-path" fill="none" stroke="#dfb96b" stroke-width="4" marker-end="url(#head)"/></svg>');updateAim(e)}))}
function updateAim(e){let d=drag;let path=document.getElementById('aim-path');if(path)path.setAttribute('d',`M${d.x} ${d.y} Q${d.x} ${e.clientY-100} ${e.clientX} ${e.clientY}`);document.querySelectorAll('.unit').forEach(u=>u.classList.remove('aimed'));let hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-entity]');if(hit&&validTarget(d.card,hit.dataset.entity))hit.classList.add('aimed')}
function validTarget(c,entity){let offensive=needsEnemy(c);return offensive?entity!=='player'&&S.run.enemies[+entity]?.hp>0:entity==='player'}
document.addEventListener('pointermove',e=>{if(!drag)return;e.preventDefault();if(drag.type==='battle')updateAim(e);else{let g=document.getElementById('drag-ghost');if(g){moveGhost(e)}}},{passive:false});
function clearDrag(){document.getElementById('aim')?.remove();document.getElementById('drag-ghost')?.remove();document.querySelectorAll('.aimed,.drag-source').forEach(el=>el.classList.remove('aimed','drag-source'));drag=null}
document.addEventListener('pointerup',e=>{if(!drag)return;let d=drag,hit=document.elementFromPoint(e.clientX,e.clientY);clearDrag();if(d.type==='field'){if(hit?.closest('.arena'))play(d.index);else toast('フィールド上で離してください')}else if(d.type==='battle'){let u=hit?.closest('[data-entity]');if(u&&validTarget(d.card,u.dataset.entity)){if(u.dataset.entity!=='player')target=+u.dataset.entity;play(d.index)}else toast('対象に重ねて離してください')}else{if(d.pointerId!=null&&d.pointerId!==e.pointerId)return;if(d.startX!=null&&!d.moved&&Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<=8&&hit?.closest('.deck-slot')===d.el){changeDeck(d.from,d.from==='deck'?'reserve':'deck',d.id);return;}let zone=hit?.closest('[data-drop]');if(d.from==='deck'){if(zone?.dataset.drop!=='deck')removeDeckKind(d.id)}else if(zone?.dataset.drop==='deck')addDeckKind(d.id)}});document.addEventListener('pointercancel',clearDrag);
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function animateEntity(key,kind,n=0,direction=1){let el=document.querySelector(`[data-entity="${key}"]`);if(!el)return;if(kind==='attack'){let a=el.animate([{transform:'translateX(0)'},{transform:`translateX(${direction*28}px)`},{transform:'translateX(0)'}],{duration:280});await a.finished}else if(kind==='hit'){el.animate([{transform:'translateX(0)'},{transform:'translateX(-9px)'},{transform:'translateX(9px)'},{transform:'translateX(-6px)'},{transform:'translateX(0)'}],{duration:320});let icon=el.querySelector('.portrait');icon.animate([{color:'#ff4a44'},{color:'#ff4a44'},{color:getComputedStyle(icon).color}],{duration:350});await delay(260)}else if(kind==='death'){await el.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(35px)'}],{duration:500,fill:'forwards'}).finished}}
play=async function(i){if(busy||page!=='battle')return;let r=S.run,c=combatCard(r.hand[i]);if(!c||r.energy<c.cost)return;busy=true;let old=r.enemies.map(e=>e.hp),oldHP=r.hp;if(c.fx.d||c.fx.poisonScale||c.fx.equalPoison||c.fx.totalPoison||c.fx.exactBlock)await animateEntity('player','attack',0,1);let savedRender=render,savedVictory=victory;render=()=>{};let won=false;victory=()=>{won=true};try{base.play(i)}finally{render=savedRender;victory=savedVictory}for(let j=0;j<r.enemies.length;j++){let diff=old[j]-r.enemies[j].hp;if(diff>0)await animateEntity(j,'hit',diff);if(old[j]>0&&r.enemies[j].hp<=0)await animateEntity(j,'death')}if(oldHP>r.hp)await animateEntity('player','hit',oldHP-r.hp);busy=false;if(r.hp<=0){await animateEntity('player','death');finish(false)}else if(won)victory();else render()};
endTurn=async function(){if(busy||page!=='battle')return;busy=true;let r=S.run;r.discard.push(...r.hand);r.hand=[];for(let i=0;i<r.enemies.length;i++){let e=r.enemies[i];if(e.hp<=0)continue;e.block=0;if(e.poison){let n=Math.min(e.hp,e.poison);e.hp-=n;e.poison--;await animateEntity(i,'hit',n);if(e.hp<=0){await animateEntity(i,'death');continue}}if(e.intent==='attack'){await animateEntity(i,'attack',0,-1);for(let hit=0;hit<(e.hits||1);hit++){let n=Math.max(0,e.atk-r.block);r.block=Math.max(0,r.block-e.atk);r.hp=Math.max(0,r.hp-n);if(n)await animateEntity('player','hit',n);if(r.hp<=0)break}}else if(e.intent==='guard')e.block=e.guardAmount||9;else e.atk+=3;if(r.hp<=0){await animateEntity('player','death');busy=false;finish(false);return}}if(r.enemies.every(e=>e.hp<=0)){busy=false;victory();return}r.turn++;r.block=r.relics.filter(x=>x.type==='b').length*3;r.energy=3;if(typeof applyTurnStartBuffs==='function')applyTurnStartBuffs(r);r.enemies.forEach(e=>{if(e.hp>0)e.intent=r.turn%3===0?'buff':r.turn%4===0?'guard':'attack'});if(typeof prepareEncounterTurn==='function')prepareEncounterTurn(r);draw(5);busy=false;render()};
function flipCards(ids,actions){return `<div class="cards reveal-list">${ids.map((id,i)=>`<div class="flip-shell ${C[id].rarity}" style="--delay:${Math.min(i*.3,2.4)}s"><div class="flip-inner"><div class="card-back">◇<small>ASHBOUND</small></div><div class="card-front">${card(id,actions?actions(id):'')}</div></div></div>`).join('')}</div>`}
reward=function(){let r=S.run;return `<div class="reward"><div class="eyebrow">VICTORY</div><h1>契約は、力となる。</h1><p>${r.kind==='boss'?'3パック・60金':'1パック・'+(r.kind==='elite'?40:20)+'金'}を獲得。</p>${r.kind==='elite'&&(r.lastRelicDrop??1)>0?`<div class="relic-reward"><div class="eyebrow">RELIC ACQUIRED</div>${relicsHTML([r.lastRelic],true)}</div>`:''}<h3>潜在カードを1枚選ぶ</h3><p>選んだカードは今回のランだけ山札に追加されます。</p>${flipCards(r.rewardCards,id=>`take(${id})`)}<div class="toolbar" style="justify-content:center"><button onclick="take(-1)">カードをスキップ →</button></div></div>`};
take=function(id){if(page!=='reward'||busy)return;let r=S.run;if(r.kind==='boss'){finish(true);return}if(id>=0)addRunCard(r,id);next()};
victory=function(){base.victory();if(S.run?.kind==='boss')finish(true)};
retreat=function(){toast('ゲームオーバー、またはボス撃破時に帰還できます')};
relic=function(){base.relic();S.discoveredRelics=S.discoveredRelics||[];if(!S.discoveredRelics.includes(S.run.lastRelic.type))S.discoveredRelics.push(S.run.lastRelic.type)};
event=function(){return `<div class="reward"><div class="eyebrow">RELIC FOUND</div><h1>灰に埋もれた遺物。</h1><div class="relic-reward">${relicsHTML([S.run.lastRelic],true)}</div><p>遺物アイコンにカーソルを重ねると能力を確認できます。</p><button class="primary" onclick="next()">探索を続ける →</button></div>`};
packs=function(){return `<div class="center"><div class="eyebrow">UNSEAL THE CONTRACT</div><h2>契約のパック</h2><p>1パックに3枚。レア以上が必ず1枚。</p>${revealed.length?flipCards(revealed):'<div class="pack"><span>ASHBOUND</span><b>◇</b><span>THE CONTRACT</span></div>'}<div class="toolbar" style="justify-content:center"><button class="primary" onclick="openPacks(1)" ${S.packs<1?'disabled':''}>1パック開封　残り ${S.packs}</button><button onclick="openPacks(S.packs)" ${S.packs<1?'disabled':''}>すべて開封 (${S.packs})</button><button onclick="buy()" ${S.gold<80?'disabled':''}>80 ◈ で購入</button><button onclick="go('deck')">デッキを編成 →</button></div></div>`};
function openPacks(n){if(S.run||n<1||n>S.packs)return;S.packs-=n;revealed=[];for(let j=0;j<n;j++)revealed.push(rand(C.filter(c=>c.rarity!=='common')).id,...Array.from({length:2},()=>rand(C.filter(c=>c.rarity===(Math.random()<.25?'rare':'common'))).id));revealed.forEach(id=>S.collection[id]=(S.collection[id]||0)+1);render()}
function book(){let found=Object.keys(S.collection).length;return `<div class="eyebrow">CODEX OF THE ASH</div><h2>カード・遺物図鑑</h2><p>未取得の能力も閲覧できます。カード ${found} / ${C.length} 種取得。</p><div class="toolbar"><button onclick="bookType='cards';render()">カード</button><button onclick="bookType='relics';render()">遺物</button><select aria-label="図鑑の絞り込み" onchange="bookFilter=this.value;render()">${[['all','すべて'],['owned','取得済み'],['common','コモン'],['rare','レア'],['epic','エピック']].map(([v,n])=>`<option value="${v}" ${bookFilter===v?'selected':''}>${n}</option>`).join('')}</select><button onclick="page=S.run?S.run.mode:'home';render()">${S.run?'探索へ':'拠点へ'}戻る →</button></div>${bookType==='cards'?`<div class="cards">${C.filter(c=>bookFilter==='all'||bookFilter==='owned'&&S.collection[c.id]||c.rarity===bookFilter).map(c=>card(c.id,'',`<span class="count">${S.collection[c.id]?'取得済み / 所持 '+S.collection[c.id]+'枚':'未取得'}</span>`)).join('')}</div>`:`<div class="tiles">${relicList.filter(x=>bookFilter!=='owned'||S.discoveredRelics?.includes(x.type)).map(x=>`<div class="tile center"><div class="portrait">${relicIcon(x)}</div><h3>${x.name}</h3><p>${rich(x.desc)}</p><span class="tag">${S.discoveredRelics?.includes(x.type)?'取得済み':'未取得'}</span></div>`).join('')||'<p>この条件の遺物はありません。</p>'}</div>`}`}
const baseRender=base.render; // Extend original page dispatch with the codex.
// Original renderer dispatch does not know book, so render its body after shared chrome.
const upgradedRender=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;upgradedRender();if(page==='book')$('app').innerHTML=book();};
if(S.run){S.run.act=S.run.act||1;if(!S.run.nodes)createMap(S.run);S.discoveredRelics=[...new Set([...(S.discoveredRelics||[]),...S.run.relics.map(x=>x.type)])]}
